let state = loadState();
let zoomMode = 'fit';

function cloneDefault() { return structuredClone(defaultState); }
function loadState() {
  try {
    let saved = THIS_LOCAL_STORAGE.getItem(STORAGE_KEY);
    let legacyUsed = false;
    if (!saved) {
      for (const key of LEGACY_STORAGE_KEYS) {
        saved = THIS_LOCAL_STORAGE.getItem(key);
        if (saved) { legacyUsed = true; break; }
      }
    }
    if (!saved) return cloneDefault();
    if (legacyUsed) THIS_LOCAL_STORAGE.setItem(STORAGE_KEY, saved);
    return mergeDefaults(cloneDefault(), JSON.parse(saved));
  } catch (error) {
    console.warn('Unable to load saved prototype', error);
    return cloneDefault();
  }
}
function mergeDefaults(base, saved) {
  const merged = { ...base, ...saved, inlineEdits: { ...(base.inlineEdits || {}), ...(saved.inlineEdits || {}) }, client: { ...base.client, ...(saved.client || {}) }, policeClearances: Array.isArray(saved.policeClearances) ? saved.policeClearances : base.policeClearances, docs: { ...base.docs } };
  Object.keys(base.docs).forEach(id => {
    merged.docs[id] = { ...base.docs[id], ...(saved.docs?.[id] || {}) };
    merged.docs[id].blocks = (saved.docs?.[id]?.blocks || base.docs[id].blocks).map((block, index) => ({ ...base.docs[id].blocks[index], ...block }));
  });
  return merged;
}

const $ = selector => document.querySelector(selector);
const $$ = selector => [...document.querySelectorAll(selector)];
const escapeHtml = value => String(value ?? '').replace(/[&<>'"]/g, ch => ({ '&':'&amp;', '<':'&lt;', '>':'&gt;', "'":'&#39;', '"':'&quot;' }[ch]));
const displayDate = value => {
  if (!value) return 'Date to be confirmed';
  const date = new Date(`${value}T12:00:00`);
  return new Intl.DateTimeFormat('en-NZ', { day: 'numeric', month: 'long', year: 'numeric' }).format(date);
};
const fullName = () => (state.client.preparedFor || `${state.client.firstName || ''} ${state.client.lastName || ''}`).trim();
const initials = label => label.split(/\s+/).map(word => word[0]).join('').slice(0,2).toUpperCase();

let inlineEditMode = false;

function hashText(value) {
  let hash = 2166136261;
  const text = String(value || '');
  for (let i = 0; i < text.length; i++) {
    hash ^= text.charCodeAt(i);
    hash = Math.imul(hash, 16777619);
  }
  return (hash >>> 0).toString(36);
}

function sanitiseInlineHtml(html) {
  const template = document.createElement('template');
  template.innerHTML = html;
  const allowed = new Set(['BR','STRONG','B','EM','I','UL','OL','LI','A']);
  [...template.content.querySelectorAll('*')].reverse().forEach(node => {
    if (!allowed.has(node.tagName)) {
      const fragment = document.createDocumentFragment();
      while (node.firstChild) fragment.appendChild(node.firstChild);
      node.replaceWith(fragment);
      return;
    }
    [...node.attributes].forEach(attribute => {
      if (!(node.tagName === 'A' && attribute.name === 'href')) node.removeAttribute(attribute.name);
    });
  });
  return template.innerHTML.trim();
}

function editCandidates(root) {
  return [...root.querySelectorAll([
    '.pdf-page:not(.pdf-cover) .pdf-page-inner p',
    '.pdf-page:not(.pdf-cover) .pdf-page-inner h2',
    '.pdf-page:not(.pdf-cover) .pdf-page-inner h3',
    '.pdf-page:not(.pdf-cover) .summary-label',
    '.pdf-page:not(.pdf-cover) .summary-value',
    '.pdf-page:not(.pdf-cover) .score-row'
  ].join(','))].filter(element => !element.closest('.page-footer, .adviser-signoff, .deadline-card'));
}

function applyInlineEdits(root, docId, makeEditable = false) {
  state.inlineEdits = state.inlineEdits || {};
  state.inlineEdits[docId] = state.inlineEdits[docId] || {};
  const overrides = state.inlineEdits[docId];
  const occurrences = {};

  editCandidates(root).forEach(element => {
    const masterHtml = element.innerHTML.trim();
    const base = `${element.tagName.toLowerCase()}-${hashText(masterHtml)}`;
    occurrences[base] = (occurrences[base] || 0) + 1;
    const key = `${base}-${occurrences[base]}`;
    element.dataset.editKey = key;
    element.dataset.masterHtml = masterHtml;
    element.classList.add('inline-editable');

    if (Object.prototype.hasOwnProperty.call(overrides, key)) {
      element.innerHTML = overrides[key];
      element.classList.add('edited-for-client');
    }

    element.contentEditable = makeEditable ? 'true' : 'false';
    element.spellcheck = makeEditable;
    if (!makeEditable) return;

    element.addEventListener('input', () => {
      $('#save-status').textContent = 'Unsaved text edits';
    });
    element.addEventListener('blur', () => {
      const cleaned = sanitiseInlineHtml(element.innerHTML);
      element.innerHTML = cleaned;
      if (cleaned === masterHtml) {
        delete overrides[key];
        element.classList.remove('edited-for-client');
      } else {
        overrides[key] = cleaned;
        element.classList.add('edited-for-client');
      }
      $('#save-status').textContent = 'Draft not saved';
    });
    element.addEventListener('keydown', event => {
      if (event.key === 'Escape') {
        element.innerHTML = Object.prototype.hasOwnProperty.call(overrides, key) ? overrides[key] : masterHtml;
        element.blur();
      }
    });
  });
  root.classList.toggle('edit-mode', makeEditable);
}

function updateInlineEditControls() {
  const toggle = $('#toggle-inline-edit');
  const reset = $('#reset-inline-edits');
  toggle.classList.toggle('active', inlineEditMode);
  toggle.textContent = inlineEditMode ? 'Done editing' : 'Edit text';
  reset.hidden = !inlineEditMode;
  const banner = $('#prototype-banner');
  banner.classList.toggle('inline-edit-help', inlineEditMode);
  banner.textContent = inlineEditMode
    ? 'Edit mode: click any outlined paragraph or heading. Changes apply only to this client draft.'
    : 'Prototype content - verify policy before client issue';
}

function renderAll() {
  renderDocumentLists();
  renderEditor();
  renderClientForm();
  renderPackSettings();
  renderPreview();
  renderOutputSummary();
  updateHeaderSummary();
}

function renderDocumentLists() {
  const initial = Object.entries(state.docs).filter(([,doc]) => doc.stage === 'initial');
  const milestone = Object.entries(state.docs).filter(([,doc]) => doc.stage === 'milestone');
  $('#document-list').innerHTML = initial.map(([id,doc]) => documentCard(id, doc)).join('');
  $('#milestone-list').innerHTML = milestone.map(([id,doc]) => documentCard(id, doc)).join('');
  $$('.document-card').forEach(card => card.addEventListener('click', event => {
    if (event.target.matches('input')) return;
    state.selectedDoc = card.dataset.doc;
    renderAll();
  }));
  $$('.document-toggle').forEach(toggle => toggle.addEventListener('change', event => {
    const id = event.target.dataset.doc;
    state.docs[id].enabled = event.target.checked;
    renderAll();
  }));
}

function documentCard(id, doc) {
  const active = state.selectedDoc === id ? 'active' : '';
  const count = doc.blocks.filter(block => block.enabled).length;
  return `<button class="document-card ${active}" data-doc="${id}">
    <span class="document-icon">${escapeHtml(doc.icon)}</span>
    <span class="document-card-copy"><span class="document-card-title">${escapeHtml(doc.label)}</span><span class="document-card-meta">${count} sections · ${doc.stage === 'milestone' ? 'later stage' : 'initial pack'}</span></span>
    <input class="document-toggle" data-doc="${id}" type="checkbox" ${doc.enabled ? 'checked' : ''} aria-label="Include ${escapeHtml(doc.label)}">
  </button>`;
}

function renderEditor() {
  const doc = state.docs[state.selectedDoc];
  $('#editor-document-title').textContent = doc.label;
  $('#editor-document-description').textContent = doc.description;
  $('#document-title').value = doc.coverTitle;
  $('#document-intro').value = doc.intro;
  $('#case-note').value = doc.caseNote;

  $('#block-editor').innerHTML = doc.blocks.map((block, index) => {
    const characterControl = state.selectedDoc === 'documents' && block.id === 'character';
    if (!characterControl) return `<label class="block-row ${block.enabled ? '' : 'disabled'}">
      <input type="checkbox" data-block-index="${index}" ${block.enabled ? 'checked' : ''}>
      <span><strong>${escapeHtml(block.title)}</strong><small>${escapeHtml(block.note)}</small></span>
      ${block.shared ? '<span class="shared-pill">Shared</span>' : ''}
    </label>`;

    return `<div class="block-row-stack ${state.policeSelectorOpen ? 'expanded' : ''}">
      <div class="block-row block-row-character ${block.enabled ? '' : 'disabled'}">
        <input id="character-block-toggle" type="checkbox" data-block-index="${index}" ${block.enabled ? 'checked' : ''}>
        <label class="block-row-copy" for="character-block-toggle"><strong>Police clearances</strong><small>${escapeHtml(block.note)} Select country instructions below.</small></label>
        <div class="block-row-actions">
          ${block.shared ? '<span class="shared-pill">Shared</span>' : ''}
          <button class="police-expand-button" id="toggle-police-selector" type="button" aria-expanded="${state.policeSelectorOpen ? 'true' : 'false'}" aria-label="${state.policeSelectorOpen ? 'Hide' : 'Show'} police clearance countries"><span class="chevron">⌄</span></button>
        </div>
      </div>
      <div id="police-library-host" class="police-library-panel" ${state.policeSelectorOpen ? '' : 'hidden'}></div>
    </div>`;
  }).join('');

  $('#block-editor').querySelectorAll('[data-block-index]').forEach(input => input.addEventListener('change', event => {
    doc.blocks[Number(event.target.dataset.blockIndex)].enabled = event.target.checked;
    renderEditor();
    renderPreview();
    renderDocumentLists();
  }));

  const policeToggle = $('#toggle-police-selector');
  if (policeToggle) policeToggle.addEventListener('click', () => {
    state.policeSelectorOpen = !state.policeSelectorOpen;
    renderEditor();
  });

  renderSubBlockEditor();
}

function getPolicePreset(country) {
  return policeCountryLibrary.find(item => item.country === country);
}

function renderSubBlockEditor() {
  const host = $('#police-library-host');
  if (!host || !state.policeSelectorOpen || state.selectedDoc !== 'documents') return;

  state.policeClearances = Array.isArray(state.policeClearances) ? state.policeClearances : [];
  const selectedNames = new Set(state.policeClearances.map(item => item.country));
  const selectedCount = state.policeClearances.length;

  host.innerHTML = `<div class="police-library-intro">
    <div><strong>Select police-clearance countries</strong><p>Tick each country required for this client. Standard wording will be inserted from the supplied Police Clearance Instructions (January 2025), and can then be edited for the individual case.</p></div>
    <span class="source-chip">January 2025 source</span>
  </div>
  <div class="country-selector-grid">${policeCountryLibrary.map(preset => `<label class="country-option ${selectedNames.has(preset.country) ? 'selected' : ''}">
    <input type="checkbox" data-police-preset="${escapeHtml(preset.country)}" ${selectedNames.has(preset.country) ? 'checked' : ''}>
    <span>${escapeHtml(preset.country)}</span>
  </label>`).join('')}</div>
  <div class="country-selection-summary">
    <div><strong>Selected country instructions</strong><br><span>${selectedCount} selected. Edit the applicant names, wording or official link below.</span></div>
    <button class="button button-secondary compact-button" id="add-custom-police-country" type="button">Add custom country</button>
  </div>
  <div class="sub-block-list">${selectedCount ? state.policeClearances.map((item,index) => {
    const preset = getPolicePreset(item.country);
    return `<div class="sub-block-item" data-police-index="${index}">
      <div class="sub-block-item-head"><strong>${escapeHtml(item.country || `Country instruction ${index + 1}`)}</strong><div class="sub-block-item-actions">${preset ? `<button class="restore-sub-block" type="button" data-reset-police="${index}">Restore standard wording</button>` : ''}<button class="remove-sub-block" type="button" data-remove-police="${index}">Remove</button></div></div>
      <div class="sub-block-grid">
        <div><label>Country</label><input class="mini-input" data-police-field="country" value="${escapeHtml(item.country || '')}" placeholder="e.g. France"></div>
        <div><label>Required for</label><input class="mini-input" data-police-field="applicants" value="${escapeHtml(item.applicants || '')}" placeholder="Applicant names"></div>
        <div class="wide"><label>Country-specific instructions</label><textarea class="mini-area" data-police-field="instructions" placeholder="Explain where to apply, what identity evidence is needed, delivery format and any special steps.">${escapeHtml(item.instructions || '')}</textarea></div>
        <div class="wide"><label>Official link (optional)</label><input class="mini-input" data-police-field="officialLink" value="${escapeHtml(item.officialLink || '')}" placeholder="https://..."></div>
      </div>
    </div>`;
  }).join('') : '<div class="field-help">No country instructions selected. Tick one or more countries above, or add a custom country.</div>'}</div>`;

  host.querySelectorAll('[data-police-preset]').forEach(control => control.addEventListener('change', event => {
    const country = event.target.dataset.policePreset;
    if (event.target.checked) {
      if (!state.policeClearances.some(item => item.country === country)) {
        const preset = getPolicePreset(country);
        state.policeClearances.push({ id: `pc-${Date.now()}-${Math.random().toString(16).slice(2)}`, country: preset.country, applicants: state.client.requiredFor || '', instructions: preset.instructions, officialLink: preset.officialLink || '' });
      }
    } else {
      state.policeClearances = state.policeClearances.filter(item => item.country !== country);
    }
    $('#save-status').textContent = 'Draft not saved';
    renderEditor();
    renderPreview();
  }));

  $('#add-custom-police-country').addEventListener('click', () => {
    state.policeClearances.push({ id: `pc-${Date.now()}`, country: '', applicants: state.client.requiredFor || '', instructions: '', officialLink: '' });
    $('#save-status').textContent = 'Draft not saved';
    renderEditor();
    renderPreview();
  });

  host.querySelectorAll('[data-remove-police]').forEach(button => button.addEventListener('click', event => {
    state.policeClearances.splice(Number(event.currentTarget.dataset.removePolice), 1);
    $('#save-status').textContent = 'Draft not saved';
    renderEditor();
    renderPreview();
  }));

  host.querySelectorAll('[data-reset-police]').forEach(button => button.addEventListener('click', event => {
    const index = Number(event.currentTarget.dataset.resetPolice);
    const current = state.policeClearances[index];
    const preset = getPolicePreset(current.country);
    if (preset) {
      current.instructions = preset.instructions;
      current.officialLink = preset.officialLink || '';
      $('#save-status').textContent = 'Draft not saved';
      renderEditor();
      renderPreview();
    }
  }));

  host.querySelectorAll('[data-police-field]').forEach(control => control.addEventListener('input', event => {
    const item = event.target.closest('[data-police-index]');
    const index = Number(item.dataset.policeIndex);
    state.policeClearances[index][event.target.dataset.policeField] = event.target.value;
    renderPreview();
    $('#save-status').textContent = 'Draft not saved';
  }));
}

function renderClientForm() {
  const fields = [
    ['firstName','First name'], ['lastName','Last name'], ['partnerName','Partner'], ['children','Dependent children'],
    ['adviser','Lead adviser'], ['adviserLicence','Licence number'], ['applicationType','Application type'], ['pathway','SMC pathway'],
    ['points','Points / basis'], ['occupation','Nominated occupation'], ['qualification','Qualifications relied on'], ['workExperience','Work experience being relied on'],
    ['workYears','Years / period claimed'], ['itaDeadline','ITA deadline'], ['requiredFor','Default required-for names','wide']
  ];
  $('#client-form').innerHTML = fields.map(([key,label,width]) => `<div class="form-section ${width || ''}">
    <label class="field-label" for="client-${key}">${label}</label>
    <input class="text-input" id="client-${key}" data-client-key="${key}" value="${escapeHtml(state.client[key])}">
  </div>`).join('');
  $('#client-form').querySelectorAll('input').forEach(input => input.addEventListener('input', event => {
    state.client[event.target.dataset.clientKey] = event.target.value;
    updateHeaderSummary();
    renderPreview();
  }));
}

function renderPackSettings() {
  $('#issue-name').value = state.issueName;
  $('#prepared-date').value = state.preparedDate;
  $('#content-status').value = state.contentStatus;
  const shared = Object.values(state.docs).flatMap(doc => doc.blocks).filter(block => block.shared && block.enabled).length;
  $('#shared-block-count').textContent = shared;
}

function updateHeaderSummary() {
  $('#client-summary-name').textContent = fullName();
  $('#client-summary-type').textContent = `${state.client.applicationType} - ${state.client.pathway}`;
}

function renderOutputSummary() {
  $$('input[name="outputMode"]').forEach(input => input.checked = input.value === state.outputMode);
  const initialEnabled = Object.values(state.docs).filter(doc => doc.stage === 'initial' && doc.enabled);
  const balancedCount = (state.docs.roadmap.enabled ? 1 : 0) + (state.docs.documents.enabled ? 1 : 0) + ((state.docs.english.enabled || state.docs.iqa.enabled) ? 1 : 0);
  const count = state.outputMode === 'combined' ? (initialEnabled.length ? 1 : 0)
    : state.outputMode === 'balanced' ? balancedCount
    : initialEnabled.length;
  $('#output-result').textContent = `Initial issue: ${count} PDF${count === 1 ? '' : 's'}`;
}

function coverPage(doc) {
  const titleParts = escapeHtml(doc.coverTitle).split(' ');
  const midpoint = Math.max(1, Math.ceil(titleParts.length / 2));
  const titleOne = titleParts.slice(0, midpoint).join(' ');
  const titleTwo = titleParts.slice(midpoint).join(' ');
  return `<section class="pdf-page pdf-cover">
    <div class="cover-top">
      <img class="cover-logo" src="data:image/png;base64," alt="THiS">
      <div class="cover-title-wrap"><div class="cover-accent"></div><div>
        <h1 class="cover-title">${titleOne}${titleTwo ? `<br><span class="mint">${titleTwo}</span>` : ''}</h1>
        ${doc.coverSubtitle ? `<div class="cover-subtitle">${escapeHtml(doc.coverSubtitle)}</div>` : ''}
      </div></div>
    </div>
    <div class="cover-image" style="background-image:url('${doc.hero}')"></div>
    <div class="cover-footer">
      <strong>PREPARED FOR - ${escapeHtml(fullName()).toUpperCase()}<br>DATE - ${escapeHtml(displayDate(state.preparedDate)).toUpperCase()}</strong>
      <em>www.turnerhopkinsimmigration.co.nz</em>
    </div>
  </section>`;
}

function pageShell(content, pageNumber, label, extraClass = '') {
  return `<section class="pdf-page pdf-content-page ${extraClass}"><div class="pdf-page-inner">${content}</div>
    <div class="page-footer"><span>${escapeHtml(label)} · Prepared for ${escapeHtml(fullName())}</span><span class="page-number">${pageNumber}</span></div>
  </section>`;
}

function numberedHeading(number, title) {
  return `<div class="number-heading"><span class="num">${String(number).padStart(2,'0')}</span><h2>${escapeHtml(title)}</h2></div>`;
}
function arrowHeading(title) { return `<div class="document-heading"><span class="heading-arrow"></span><h2>${escapeHtml(title)}</h2></div>`; }
function flowSection(content, compact = false) {
  return `<section class="flow-section ${compact ? 'compact' : ''}">${content}</section>`;
}

function signoff() {
  return `<div class="adviser-signoff"><strong>${escapeHtml(state.client.adviser)}</strong><span>Licensed Immigration Adviser - ${escapeHtml(state.client.adviserLicence)}</span><span>Turner Hopkins Immigration Specialists</span></div>`;
}

function renderRoadmap(doc) {
  const enabled = id => doc.blocks.find(block => block.id === id)?.enabled;
  const pages = [coverPage(doc)];
  let p = 1;

  const firstSections = [];
  firstSections.push(flowSection(`${numberedHeading(1,'Introduction')}
    <p>Dear ${escapeHtml(state.client.firstName)}</p><p class="intro-line">Your New Zealand journey starts here.</p>
    <p>${escapeHtml(doc.intro)}</p>
    <div class="callout"><span class="callout-icon">i</span><p>${escapeHtml(doc.caseNote)}</p></div>`));

  if (enabled('strategy')) firstSections.push(flowSection(`${numberedHeading(2,'Your strategy')}<p>We are preparing a pathway under the <strong>${escapeHtml(state.client.applicationType)}</strong>. The final structure will be confirmed against the operative instructions and the evidence available for your case.</p>
    <div class="strategy-grid">
      ${[['Plan & prepare','Gather the evidence and complete any preliminary assessments.'],['Employment','Review the role, employer and job offer against the selected pathway.'],['Temporary visas','Use temporary visas where required to support the wider migration plan.'],['Residence','Prepare, review and lodge the residence application when the requirements are met.']].map((item,i)=>`<div class="strategy-card"><span class="card-number">${i+1}</span><h3>${item[0]}</h3><p>${item[1]}</p></div>`).join('')}
    </div>`, true));

  if (enabled('points')) firstSections.push(flowSection(`<div class="summary-panel"><span class="summary-label">Current strategy summary</span><div class="summary-value">${escapeHtml(state.client.points)}</div><p><strong>Pathway:</strong> ${escapeHtml(state.client.pathway)}<br><strong>Occupation:</strong> ${escapeHtml(state.client.occupation)}</p></div>`, true));
  pages.push(pageShell(firstSections.join(''),p++,doc.label));

  if (enabled('timeline')) {
    const steps = [
      ['Step 1','Documentation','Gather identity, civil, employment, qualification and family evidence.','1 to 3 months - indicative'],
      ['Step 2','Assessments and registration','Complete IQA or professional registration where relevant.','Depends on the assessing body'],
      ['Step 3','Employment and visa preparation','Review job-search material, job offers and any temporary visa requirements.','Case dependent'],
      ['Step 4','Residence application','Prepare the application, provide a draft for review and lodge when ready.','Confirmed at lodgement stage'],
      ['Step 5','Decision and next steps','Manage INZ queries, approval and post-residence planning.','Depends on INZ processing']
    ];
    pages.push(pageShell(flowSection(`${numberedHeading(3,'Steps & timelines')}<p>The steps below are a planning framework. We will adjust the order and timing where the evidence, employment position or immigration instructions require it.</p><div class="timeline">${steps.map(step=>`<div class="timeline-item"><span class="timeline-step">${step[0]}</span><div><h3>${step[1]}</h3><p>${step[2]}</p><span class="time-pill">◷ ${step[3]}</span></div></div>`).join('')}</div>`),p++,doc.label));
  }

  const lastSections = [];
  if (enabled('employment')) lastSections.push(flowSection(`${numberedHeading(4,'Skilled employment')}<p>A significant part of the strategy may involve securing employment that meets the selected pathway. We will review the role, employer, hours, duration, remuneration and relationship to your skills before relying on it.</p>
    <div class="requirement-list">${[['Accredited employer','Confirm the employer status required by the relevant visa or residence pathway.'],['Employment terms','Check hours, duration, duties and supporting employment documents.'],['Skill and relevance','Assess the role against the applicable occupation and pathway requirements.'],['Remuneration','Confirm the required hourly rate or salary calculation at the relevant date.']].map((r,i)=>`<div class="requirement-row"><span class="requirement-number">${i+1}</span><div><h3>${r[0]}</h3><p>${r[1]}</p></div></div>`).join('')}</div>`));
  if (enabled('next')) lastSections.push(flowSection(`${numberedHeading(5,'Questions & next steps')}<p>Your first priority is to review this Road Map and then work through the Documentation Guide. The specialist guides included in your pack explain any separate assessment or English-language steps.</p><div class="callout"><span class="callout-icon">✓</span><p><strong>Immediate action:</strong> Start with identity and qualification documents, and tell us about anything that may be difficult to obtain.</p></div>${signoff()}`, true));
  if (lastSections.length) pages.push(pageShell(lastSections.join(''),p++,doc.label));
  return pages.join('');
}

const docDescriptions = {
  identity: ['Identity documents','Identity and civil-status records used to establish each applicant’s name, date of birth, nationality and family relationships.'],
  relationship: ['Relationship evidence','Evidence showing that the partners live together in a genuine and stable relationship, tailored to the relevant period and application.'],
  custody: ['Custody and dependence','Custody, consent, relationship and dependence evidence for any child included in the application.'],
  work: ['Work experience','Detailed employment references and independent supporting records for the work experience being relied on.'],
  qualifications: ['Qualifications','Formal award certificates, complete academic transcripts and any supporting name-change or verification records.'],
  character: ['Character - police certificates','General character guidance followed by repeatable country-specific instruction blocks.'],
  health: ['Health - medicals and chest X-rays','Client-specific medical certificate, chest X-ray and panel physician instructions, including when the examinations should be completed.'],
  forms: ['Application forms and declarations','Draft online forms, client review and any declarations or authority forms required before submission.']
};

function listItems(items) {
  return `<ul>${items.map(item=>`<li>${escapeHtml(item)}</li>`).join('')}</ul>`;
}

function renderPoliceSubBlocks() {
  const items = (state.policeClearances || []).filter(item => item.country || item.instructions || item.applicants);
  if (!items.length) return `<div class="callout"><span class="callout-icon">i</span><p>No country-specific police certificate instructions have been selected. Open the Police clearances card in the Content panel and tick the relevant countries.</p></div>`;
  return items.map(item => `<div class="country-instruction">
    <div class="country-instruction-head"><h3>${escapeHtml(item.country || 'Country to be confirmed')}</h3><span class="applicant-chip">Required for: ${escapeHtml(item.applicants || state.client.requiredFor)}</span></div>
    <p>${escapeHtml(item.instructions || 'Country-specific application instructions to be inserted.').replace(/\n/g, '<br>')}</p>
    ${item.officialLink ? `<p><strong>Official source:</strong> <a href="${escapeHtml(item.officialLink)}" target="_blank" rel="noopener">${escapeHtml(item.officialLink)}</a></p>` : ''}
  </div>`).join('');
}

function renderDocumentDetail(block) {
  const requiredFor = escapeHtml(state.client.requiredFor);
  if (block.id === 'identity') return `${arrowHeading('Identity documents')}
    <p>Provide the civil and identity records listed for each applicant. Documents must show the complete record and all relevant names, dates and issuing details.</p>
    <div class="detail-box"><h3>Typical documents</h3>${listItems(['Full birth certificate showing both parents’ names, where available.','Current passport personal-details page, including issue and expiry information.','Digital passport photograph in the requested image format.','Marriage, divorce or legal name-change evidence where relevant.'])}</div>
    <div class="required-for">Required for: ${requiredFor}</div>`;
  if (block.id === 'relationship') return `${arrowHeading('Relationship evidence')}
    <p>We need evidence that demonstrates the relationship is genuine, stable and based on living together. The evidence should cover the period relevant to the application rather than only showing the current position.</p>
    <div class="detail-box"><h3>Useful evidence</h3>${listItems(['Joint tenancy, mortgage, utility, banking or insurance records showing both names and the shared address.','Separate correspondence addressed to each partner at the same residential address.','A limited selection of photographs showing the relationship over time and in different settings.','Short supporting statements from friends or family who know the relationship.'])}</div>
    <p>Continue gathering current evidence while the application is being prepared so the record can be updated before lodgement.</p><div class="required-for">Required for: ${requiredFor}</div>`;
  if (block.id === 'custody') return `${arrowHeading('Custody and dependence')}
    <p>Where a child is included, the required evidence depends on age, living arrangements, the involvement of the other parent and whether the child remains dependent.</p>
    <div class="detail-box"><h3>Evidence may include</h3>${listItems(['Birth certificate establishing the relationship to the child.','Custody order, parenting agreement or written consent from the other parent.','Evidence of the child’s residence and financial dependence.','School, study or other records relevant to ongoing dependence.'])}</div>
    <p>Tell us immediately if consent may be difficult to obtain or if there are existing parenting or protection orders.</p><div class="required-for">Required for: ${requiredFor}</div>`;
  if (block.id === 'work') return `${arrowHeading('Work experience')}
    <p>The work experience being relied on is: <strong>${escapeHtml(state.client.workExperience)}</strong>. Period or years claimed: <strong>${escapeHtml(state.client.workYears)}</strong>.</p>
    <div class="detail-box"><h3>Employer reference requirements</h3>${listItems(['Issued on company letterhead or other official stationery.','Confirms the employee’s full name, job title, start and end dates, and whether the role was full-time or the usual hours worked.','Contains a sufficiently detailed description of the principal duties, responsibilities and level of the role.','Dated and signed by a person with authority to verify the employment, with their name, position and current contact details.','Explains any material change in title, duties, hours or location during the period claimed.'])}</div>
    <div class="detail-box"><h3>Supporting evidence</h3>${listItems(['Employment agreements and job descriptions.','Payslips, tax records or social-security records linking the employee to the employer and period claimed.','Certificates of service, appraisal records or promotion letters.','Evidence explaining a business closure, unavailable referee or other gap in the primary evidence.'])}</div>
    <div class="callout"><span class="callout-icon">i</span><p>INZ may contact current or former employers to verify the reference and the claimed employment. Tell us before obtaining the reference if the employer cannot be contacted or the required wording will be difficult to secure.</p></div><div class="required-for">Required for: ${requiredFor}</div>`;
  if (block.id === 'qualifications') return `${arrowHeading('Qualifications')}
    <div class="summary-panel"><span class="summary-label">Qualifications being relied on</span><div class="summary-value">${escapeHtml(state.client.qualification)}</div><p>Confirm that the title, awarding institution and completion details match the supporting records.</p></div>
    <div class="detail-box"><h3>Award certificate</h3>${listItems(['Provide the formal certificate issued by the awarding institution confirming the complete qualification title.','Scan the whole document in colour, with no missing edges, folds or obscured information.','A completion letter or statement of eligibility to graduate is not normally a substitute for the final award certificate unless we confirm otherwise.','Provide the original-language document together with an official English translation where required.'])}</div>
    <div class="detail-box"><h3>Academic transcript</h3>${listItems(['Provide the complete transcript or mark sheet showing subjects, courses and results.','Include every page and any reverse-side information, grading key or legend.','If study was completed at more than one institution or credits were transferred, provide records from each institution involved.','Provide name-change evidence if the qualification records are in a different name from the current passport.'])}</div>
    <p>Contact the institution early if replacement records are required, as archived documents and verification requests can take time.</p><div class="required-for">Required for: ${requiredFor}</div>`;
  if (block.id === 'character') return `${arrowHeading('Character - police certificates')}
    <p>We will identify which applicants require police certificates and the countries from which they must be obtained. Requirements differ according to citizenship, travel and residence history, the type of visa and the relevant assessment period.</p>
    <div class="callout"><span class="callout-icon">i</span><p>Country processes can change. The country wording below is drawn from the supplied January 2025 instruction library and remains editable. Check the recorded official source and contact us before applying if fingerprints, identity checks, adviser requests or direct delivery to INZ are required.</p></div>
    ${renderPoliceSubBlocks()}`;
  if (block.id === 'health') return `${arrowHeading('Health - medicals and chest X-rays')}
    <p>We will confirm separately who requires a medical certificate, chest X-ray or limited medical examination and the correct timing. Examinations must be completed through an approved panel physician where that is required.</p>
    <div class="detail-box"><h3>Before booking</h3>${listItems(['Wait for our confirmation so the examination is not completed too early.','Use the applicant’s passport details exactly as shown in the visa application.','Tell us about any existing condition, specialist treatment, surgery or regular medication so supporting reports can be considered.','Retain the eMedical reference or other confirmation provided by the clinic.'])}</div><div class="required-for">Required for: ${requiredFor}</div>`;
  return `${arrowHeading('Application forms and declarations')}
    <p>We will prepare the online application using the information held in the CRM and the documents supplied. A draft will be provided for review before submission.</p>
    <div class="detail-box"><h3>Your review</h3>${listItems(['Read every answer carefully and identify anything incomplete, inaccurate or out of date.','Check names, dates, travel history, employment, qualifications, health and character disclosures.','Sign and date any declaration or authority form in the required places.','Do not sign an outdated form in advance; we will provide the current version when it is needed.'])}</div><div class="required-for">Required for: ${requiredFor}</div>`;
}

function renderDocuments(doc) {
  const activeBlocks = doc.blocks.filter(block => block.enabled);
  const pages = [coverPage(doc)];
  let p = 1;
  const checklist = activeBlocks.map(block => `<tr><td>${escapeHtml(block.title)}</td><td>${escapeHtml(state.client.requiredFor)}</td><td><span class="tick-box"></span></td></tr>`).join('');

  pages.push(pageShell([
    flowSection(`${numberedHeading(1,'Introduction')}<p>Dear ${escapeHtml(state.client.firstName)}</p><p>${escapeHtml(doc.intro)}</p>`),
    flowSection(`${numberedHeading(2,'Preparing your documents')}
      <p>Most records can be supplied as clear colour scans, but document quality matters. Poor scans, incomplete pages or informal translations can delay preparation and may need to be replaced.</p>
      <div class="detail-box"><h3>Colour scans and PDF files</h3>${listItems(['Scan from the original document in colour and at a resolution that keeps all text, stamps, seals and photographs clear when enlarged.','Include the complete page and all edges. Avoid shadows, fingers, glare, folds or cropped information.','Combine a multi-page document into one PDF in the correct order. Do not send screenshots, Word files or separate phone photographs unless we specifically request them.','Do not password-protect the file. Passport photographs are the main exception and should be supplied in the image format we request.'])}</div>
      <div class="detail-box"><h3>Official translations</h3>${listItems(['Provide both the original-language document and the complete English translation.','Use an independent professional or official translation service rather than translating the document yourself or using a friend or relative.','The translation should identify the translator or service and should cover stamps, handwritten entries and reverse-side text as well as the main wording.','Names and dates should be consistent with the passport. Draw any variation to our attention rather than altering the document.'])}</div>
      <div class="detail-box"><h3>File names and delivery</h3>${listItems(['Use a clear file name containing the document type and applicant name, for example: Birth Certificate - Alex Morgan.pdf.','Keep one document in each file unless the pages form part of the same record.','Retain the original document and your own organised copy of everything sent to us.','Tell us promptly if a document is unavailable, delayed, damaged or different from the description in this guide.'])}</div>`, true)
  ].join(''),p++,doc.label));

  pages.push(pageShell(flowSection(`${numberedHeading(3,'Your checklist')}<p>This summary is generated from the sections selected for your case. The detailed pages that follow explain what is needed, the expected content and who it is required for.</p><table class="checklist-table"><thead><tr><th>Document type</th><th>Required for</th><th>Complete</th></tr></thead><tbody>${checklist}</tbody></table><div class="callout"><span class="callout-icon">i</span><p>${escapeHtml(doc.caseNote)}</p></div>`),p++,doc.label));

  activeBlocks.forEach((block, index) => {
    const includeHints = index === activeBlocks.length - 1;
    const content = [flowSection(renderDocumentDetail(block))];
    if (includeHints) content.push(flowSection(`${numberedHeading(4,'Helpful hints')}<div class="strategy-grid">${[['Timing','Check which documents are needed now and which should wait until lodgement.'],['Naming','Name every file clearly and keep your own organised copy.'],['Checklist','Use the summary table to track progress as documents are gathered.'],['Ask us','Contact us before spending time or money on an uncertain document.']].map((r,i)=>`<div class="strategy-card"><span class="card-number">${i+1}</span><h3>${r[0]}</h3><p>${r[1]}</p></div>`).join('')}</div>${signoff()}`, true));
    pages.push(pageShell(content.join(''),p++,doc.label));
  });
  return pages.join('');
}

function renderEnglish(doc) {
  const pages=[coverPage(doc)]; let p=1;
  const principal = fullName();
  pages.push(pageShell([
    flowSection(`${numberedHeading(1,'Introduction')}<p>Dear ${escapeHtml(state.client.firstName)}</p><p>${escapeHtml(doc.intro)}</p><div class="callout"><span class="callout-icon">i</span><p>${escapeHtml(doc.caseNote)}</p></div>`),
    flowSection(`${numberedHeading(2,'Test overview')}<p>English evidence may be demonstrated in different ways depending on the applicant and the relevant instructions. Where a test is required, the guide can display only the approved options selected for the client.</p><p>Test content normally covers reading, writing, speaking and listening. The adviser-controlled score fields below are placeholders in this prototype and must be confirmed before issue.</p>`, true)
  ].join(''),p++,doc.label));
  pages.push(pageShell([
    flowSection(`${arrowHeading('Test options')}<div class="test-grid"><div class="test-card"><h3>IELTS</h3><p>A recognised test completed through an approved testing provider. The correct test type should be confirmed before booking.</p><div class="score-row"><strong>${escapeHtml(principal)}</strong><br>Overall score: adviser to confirm</div><div class="score-row"><strong>${escapeHtml(state.client.partnerName || 'Partner')}</strong><br>Requirement: adviser to confirm</div></div><div class="test-card"><h3>Pearson PTE</h3><p>A computer-based test option. The accepted test and score should be confirmed against the operative instructions.</p><div class="score-row"><strong>${escapeHtml(principal)}</strong><br>Overall score: adviser to confirm</div><div class="score-row"><strong>${escapeHtml(state.client.partnerName || 'Partner')}</strong><br>Requirement: adviser to confirm</div></div></div>`),
    flowSection(`${numberedHeading(3,'Results')}<p>Send the formal result evidence to us as soon as it is available. We will confirm whether an electronic result, official report or direct verification is required for the application.</p>${signoff()}`, true)
  ].join(''),p++,doc.label));
  return pages.join('');
}

function renderIqa(doc) {
  const pages=[coverPage(doc)]; let p=1;
  pages.push(pageShell([
    flowSection(`${numberedHeading(1,'Introduction')}<p>Dear ${escapeHtml(state.client.firstName)}</p><p>${escapeHtml(doc.intro)}</p><div class="summary-panel"><span class="summary-label">Qualification being assessed</span><div class="summary-value">${escapeHtml(state.client.qualification)}</div><p>Applicant: ${escapeHtml(fullName())}</p></div>`),
    flowSection(`${numberedHeading(2,'Documentation required')}<div class="requirement-list">${[['Qualification certificate','A clear colour copy of the formal award certificate.'],['Academic transcript','The complete subject and results record for the qualification.'],['Identity document','The personal details page of the current passport and any name-change evidence.'],['Verification','Additional third-party verification if requested by the assessing authority.']].map((r,i)=>`<div class="requirement-row"><span class="requirement-number">${i+1}</span><div><h3>${r[0]}</h3><p>${r[1]}</p></div></div>`).join('')}</div>`, true)
  ].join(''),p++,doc.label));
  pages.push(pageShell(flowSection(`${numberedHeading(3,'Application process')}<div class="timeline">${[['1','Prepare','We prepare the online assessment using the information and documents supplied.'],['2','Review','A draft is provided for checking and any corrections are made.'],['3','Submit','The application is submitted after approval and payment arrangements are confirmed.'],['4','Respond','We manage requests for verification or further information.']].map(step=>`<div class="timeline-item"><span class="timeline-step">Step ${step[0]}</span><div><h3>${step[1]}</h3><p>${step[2]}</p></div></div>`).join('')}</div><div class="callout"><span class="callout-icon">i</span><p>${escapeHtml(doc.caseNote)}</p></div>${signoff()}`),p++,doc.label));
  return pages.join('');
}

function renderIta(doc) {
  const pages=[coverPage(doc)]; let p=1;
  const active = doc.blocks.filter(block=>block.enabled);
  pages.push(pageShell(flowSection(`${numberedHeading(1,'Introduction')}<p>Dear ${escapeHtml(state.client.firstName)}</p><p>${escapeHtml(doc.intro)}</p><div class="deadline-card"><div><span>Lodgement deadline</span><strong>${escapeHtml(state.client.itaDeadline)}</strong></div><div class="tick-box"></div></div><div class="callout"><span class="callout-icon">i</span><p>${escapeHtml(doc.caseNote)}</p></div>`),p++,doc.label));
  pages.push(pageShell([
    flowSection(`${numberedHeading(2,'Outstanding documents')}<p>This checklist is intended to pull live status information from the CRM at the time the guide is generated.</p><table class="checklist-table"><thead><tr><th>Outstanding item</th><th>Required for</th><th>Complete</th></tr></thead><tbody>${active.map(block=>`<tr><td>${escapeHtml(block.title)}</td><td>${escapeHtml(state.client.requiredFor)}</td><td><span class="tick-box"></span></td></tr>`).join('')}</tbody></table>`),
    flowSection(`${numberedHeading(3,'Next steps')}<div class="timeline">${[['1','Finalise evidence','Resolve the outstanding checklist and confirm document quality.'],['2','Prepare draft','Complete the online application and provide a copy for review.'],['3','Lodge','Submit before the deadline and pay the applicable fee.'],['4','Manage processing','Respond to INZ requests and keep the client updated.']].map(step=>`<div class="timeline-item"><span class="timeline-step">Step ${step[0]}</span><div><h3>${step[1]}</h3><p>${step[2]}</p></div></div>`).join('')}</div>${signoff()}`, true)
  ].join(''),p++,doc.label));
  return pages.join('');
}

function renderDocHtml(id) {
  const doc = state.docs[id];
  if (id === 'roadmap') return renderRoadmap(doc);
  if (id === 'documents') return renderDocuments(doc);
  if (id === 'english') return renderEnglish(doc);
  if (id === 'iqa') return renderIqa(doc);
  return renderIta(doc);
}

function renderPreview() {
  const doc = state.docs[state.selectedDoc];
  $('#preview-title').textContent = doc.label;
  const root = $('#preview-root');
  root.className = `preview-root zoom-${zoomMode}`;
  root.innerHTML = renderDocHtml(state.selectedDoc);
  applyInlineEdits(root, state.selectedDoc, inlineEditMode);
  updateInlineEditControls();
}

function printOrder() {
  const enabledInitial = ['roadmap','documents','english','iqa'].filter(id => state.docs[id].enabled);
  const enabledMilestones = ['ita'].filter(id => state.docs[id].enabled);
  return [...enabledInitial, ...enabledMilestones];
}
function preparePrint() {
  const ids = printOrder();
  const printRoot = $('#print-root');
  printRoot.innerHTML = ids.map(id => `<div class="print-document" data-doc-id="${id}">${renderDocHtml(id)}</div>`).join('');
  printRoot.querySelectorAll('.print-document').forEach(container => applyInlineEdits(container, container.dataset.docId, false));
  setTimeout(() => window.print(), 120);
}

function saveDraft() {
  state.issueName = $('#issue-name').value;
  state.preparedDate = $('#prepared-date').value;
  state.contentStatus = $('#content-status').value;
  THIS_LOCAL_STORAGE.setItem(STORAGE_KEY, JSON.stringify(state));
  $('#save-status').textContent = `Saved ${new Date().toLocaleTimeString('en-NZ',{hour:'2-digit',minute:'2-digit'})}`;
  showToast('Draft saved in this browser');
  renderPreview();
}

function exportJson() {
  const blob = new Blob([JSON.stringify(state,null,2)], { type:'application/json' });
  const url = URL.createObjectURL(blob);
  const link = document.createElement('a');
  link.href = url;
  link.download = `this-smc-instruction-pack-${state.client.lastName || 'client'}.json`;
  link.click();
  URL.revokeObjectURL(url);
}

function publishItems() {
  const docs = Object.values(state.docs).filter(doc=>doc.enabled);
  if (state.outputMode === 'combined') {
    const items = [];
    if (Object.values(state.docs).some(doc => doc.stage === 'initial' && doc.enabled)) items.push('Combined initial SMC instruction pack');
    if (state.docs.ita.enabled) items.push('Invitation to Apply');
    return items;
  }
  if (state.outputMode === 'balanced') {
    const items=[];
    if (state.docs.roadmap.enabled) items.push('Introduction & Road Map');
    if (state.docs.documents.enabled) items.push('Documentation Guide');
    if (state.docs.english.enabled || state.docs.iqa.enabled) items.push('Specialist Guides');
    if (state.docs.ita.enabled) items.push('Invitation to Apply');
    return items;
  }
  return docs.map(doc=>doc.label);
}
function openPublishModal() {
  const items=publishItems();
  $('#publish-summary').textContent = `${state.issueName} will be generated as ${items.length} PDF${items.length===1?'':'s'} and added to ${fullName()}'s portal.`;
  $('#publish-list').innerHTML = items.map((item,index)=>`<div><span>${String(index+1).padStart(2,'0')}</span><strong>${escapeHtml(item)}</strong></div>`).join('');
  $('#publish-modal').hidden=false;
}
function closeModal(){ $('#publish-modal').hidden=true; }
function showToast(message){ const toast=$('#toast'); toast.textContent=message; toast.classList.add('show'); setTimeout(()=>toast.classList.remove('show'),2600); }

function bindEvents() {
  $$('.editor-tab').forEach(tab => tab.addEventListener('click', () => {
    $$('.editor-tab').forEach(item=>item.classList.toggle('active',item===tab));
    $$('.tab-pane').forEach(pane=>pane.classList.toggle('active',pane.id===`tab-${tab.dataset.tab}`));
  }));
  $('#document-title').addEventListener('input', event => { state.docs[state.selectedDoc].coverTitle=event.target.value; renderPreview(); renderDocumentLists(); });
  $('#document-intro').addEventListener('input', event => { state.docs[state.selectedDoc].intro=event.target.value; renderPreview(); });
  $('#case-note').addEventListener('input', event => { state.docs[state.selectedDoc].caseNote=event.target.value; renderPreview(); });
  $('#enable-all-blocks').addEventListener('click', () => { state.docs[state.selectedDoc].blocks.forEach(block=>block.enabled=true); renderAll(); });
  $('#cover-upload').addEventListener('change', event => {
    const file=event.target.files[0]; if(!file) return;
    const reader=new FileReader(); reader.onload=()=>{ state.docs[state.selectedDoc].hero=reader.result; renderPreview(); showToast('Cover image replaced for this draft'); }; reader.readAsDataURL(file);
  });
  $('#edit-client-shortcut').addEventListener('click',()=>$('.editor-tab[data-tab="client"]').click());
  $$('input[name="outputMode"]').forEach(input=>input.addEventListener('change',event=>{state.outputMode=event.target.value;renderOutputSummary();}));
  $$('.segmented[data-zoom]').forEach(button=>button.addEventListener('click',()=>{ zoomMode=button.dataset.zoom==='100'?'100':'fit'; $$('.segmented[data-zoom]').forEach(item=>item.classList.toggle('active',item===button)); renderPreview(); }));
  $('#toggle-inline-edit').addEventListener('click',()=>{ inlineEditMode=!inlineEditMode; renderPreview(); });
  $('#reset-inline-edits').addEventListener('click',()=>{
    const edits = state.inlineEdits?.[state.selectedDoc] || {};
    if (!Object.keys(edits).length) { showToast('There are no client text edits to reset'); return; }
    if (confirm('Reset all direct text edits in this guide to the master wording?')) {
      state.inlineEdits[state.selectedDoc] = {};
      renderPreview();
      $('#save-status').textContent = 'Draft not saved';
      showToast('Client text edits reset');
    }
  });
  $('#issue-name').addEventListener('input',event=>state.issueName=event.target.value);
  $('#prepared-date').addEventListener('input',event=>{state.preparedDate=event.target.value;renderPreview();});
  $('#content-status').addEventListener('change',event=>state.contentStatus=event.target.value);
  $('#save-draft').addEventListener('click',saveDraft);
  $('#export-json').addEventListener('click',exportJson);
  $('#print-pack').addEventListener('click',preparePrint);
  $('#publish-pack').addEventListener('click',openPublishModal);
  $('#close-modal').addEventListener('click',closeModal);
  $('#cancel-publish').addEventListener('click',closeModal);
  $('#confirm-publish').addEventListener('click',()=>{closeModal();showToast('Instructions marked ready');});
  $('#publish-modal').addEventListener('click',event=>{if(event.target.id==='publish-modal')closeModal();});
  $('#reset-draft').addEventListener('click',()=>{if(confirm('Reset this instruction draft to its original content?')){THIS_LOCAL_STORAGE.removeItem(STORAGE_KEY);LEGACY_STORAGE_KEYS.forEach(key => THIS_LOCAL_STORAGE.removeItem(key));state=cloneDefault();renderAll();showToast('Instruction draft reset');}});
}


