v12EnsureClientDefaults();

function v12SafeClientHtml(source) {
  let html = String(source || '');
  const replacements = [
    [/the information held in the CRM/gi, 'the information already provided to us'],
    [/live status information from the CRM/gi, 'the current outstanding items for this application'],
    [/instruction library/gi, 'country-specific guidance'],
    [/prototype content/gi, 'draft content'],
    [/placeholders? in this prototype/gi, 'figures recorded for this application'],
    [/adviser to confirm/gi, 'as recorded for this application'],
    [/recorded in the client data/gi, 'set out in this guide'],
    [/if an assessment is required/gi, 'for the assessment required for this application'],
    [/if this is required/gi, 'for this confirmed requirement'],
    [/if required/gi, 'where shown as required in this guide'],
    [/where relevant/gi, 'for the applicants identified in this guide'],
    [/may be required/gi, 'is required where listed in this guide'],
    [/could be required/gi, 'is required where listed in this guide']
  ];
  replacements.forEach(([pattern,replacement]) => { html = html.replace(pattern,replacement); });
  return html;
}

