function v12QualitySpec(block) {
  const map = {
    identity:['Complete, current records with names and dates matching the passport.','Cropped pages, glare, expired documents or unexplained name differences.'],
    relationship:['A continuous, dated record from several independent sources showing living together.','Photographs alone, large undated bundles or evidence from only one short period.'],
    custody:['Formal records that clearly establish legal authority, consent and the child’s identity.','Informal messages, unsigned statements or documents that do not identify the child.'],
    work:['Detailed duties, exact dates, hours and an authorised referee, supported independently.','References confirming only a job title, vague duties or unverifiable employment.'],
    employment:['Signed, complete and consistent employment documents matching the approved role.','Unsigned agreements, conflicting duties or missing schedules and job descriptions.'],
    skills:['Evidence that precisely matches the qualification or experience requirement in the Job Check.','Unrelated qualifications, generic references or records covering too little experience.'],
    qualifications:['The final award, full transcript and identity link for the exact qualification relied on.','Provisional results, incomplete transcripts or records in an unexplained different name.'],
    docs:['The final award, full transcript and verification records for the exact assessed qualification.','Incomplete academic records or a different award from the one used in the application.'],
    character:['The correct national certificate, issued for the named applicant through the official process.','Local-only checks, expired certificates or a certificate obtained for the wrong purpose.'],
    health:['Correct passport identity, approved clinic records and relevant specialist reports.','Booking too early, using inconsistent identity details or omitting existing conditions.'],
    forms:['Answers that are complete, current and consistent with every supporting document.','Signing an old form, leaving gaps or approving details that have changed.'],
    assets:['Clear ownership, valuation and the ability to liquidate and transfer the nominated asset.','Unexplained joint ownership, outdated values or assets that cannot be traced.'],
    lawful:['A continuous evidence trail from the original earnings or transaction to the current funds.','Large unexplained deposits, missing tax records or breaks in the movement of funds.'],
    sponsor:['Current evidence connecting the sponsor to the applicant and proving status, address and income.','Old income records, incomplete status evidence or no proof of the family relationship.'],
    english:['The accepted test or other evidence for the named applicant, within its validity period.','The wrong test type, incomplete score report or identity details that do not match the passport.'],
    birth:['A full certificate showing the child and both parents, where the issuing country provides this.','Short-form certificates or records that do not establish the parental relationship.'],
    referee:['A referee who meets every eligibility rule and remains available to verify the application.','A relative, household member or person without the required New Zealand passport details.'],
    check:['An identity check completed using the approved method and the same identity details as the application.','Sharing passwords, using another person’s account or incomplete identity verification.'],
    offer:['A final, current offer showing provider, programme, dates, fees and study load.','Conditional or outdated offers, missing pages or inconsistent course details.'],
    funds:['Complete statements showing ownership, availability, transaction history and source.','Screenshots, unexplained deposits, borrowed funds not disclosed or cropped statements.'],
    accommodation:['A signed, dated arrangement supported by the host’s identity, status and address evidence.','Informal messages or a host letter without dates, address or supporting records.'],
    insurance:['Cover that meets the provider and visa requirements for the full required period.','A quote rather than confirmed cover, or a policy with incorrect dates or exclusions.'],
    ties:['Objective, current evidence supporting the reasons the applicant will leave New Zealand.','General statements without employment, family, property or financial records.'],
    travel:['A clear chronology supported by visa records and passport stamps.','Unexplained gaps, missing passports or dates that conflict with the application.'],
    fee:['The current amount and secure payment method confirmed immediately before filing.','Sending card details by ordinary email or relying on an outdated fee figure.'],
    outstanding:['Every item complete, current and consistent before the filing deadline.','Assuming an incomplete item can be supplied later without discussing it with us.']
  };
  return map[block.id] || ['Clear, complete and consistent evidence that directly supports this application.','Incomplete pages, poor scans, unexplained differences or records that do not cover the required period.'];
}

