function v12NextThreeSection(doc) {
  const priorities = v12PriorityItems(doc);
  const rows = priorities.map((item,index)=>`<div class="next-three-row"><span class="next-three-number">${index+1}</span><div><h3>${['Start with the first priority','Prepare and name the evidence','Tell us about any issue'][index]}</h3><p>${escapeHtml(item)}</p></div></div>`).join('');
  return flowSection(`${numberedHeading(90,'Your next three steps')}<div class="next-three"><div class="next-three-list">${rows}</div></div>`,true);
}

function renderStructuredDoc(doc) {
  const enabled = doc.blocks.filter(block => block.enabled);
  const pages = [coverPage(doc)];
  let pageNo = 1;
  pages.push(v12AtAGlancePage(doc,pageNo++));
  const introText = v12SafeClientHtml(fillTemplate(doc.intro || ''));
  const introParagraphs = introText.split(/\n\s*\n/).filter(Boolean).map(item => `<p>${item}</p>`).join('');
  const noteText = v12SafeClientHtml(fillTemplate(doc.caseNote || ''));
  const intro = flowSection(`${numberedHeading(1,'Introduction')}<p>Dear ${escapeHtml(state.client.firstName || 'Client')}</p>${introParagraphs}${noteText?`<div class="callout"><span class="callout-icon">i</span><p>${noteText}</p></div>`:''}`);
  let groups=[]; let current=[intro]; let units=textUnits(intro); const capacity=4300;
  enabled.forEach((block,index)=>{
    const rendered=genericBlockHtml(block,index);
    const nextUnits=textUnits(rendered);
    if ((block.forcePage || units + nextUnits > capacity) && current.length) { groups.push(current); current=[]; units=0; }
    current.push(rendered); units += nextUnits;
  });
  if (current.length) groups.push(current);
  groups.forEach(group => pages.push(pageShell(group.join(''),pageNo++,doc.label)));
  const closing = `${v12NextThreeSection(doc)}${flowSection(signoff(),true)}`;
  pages.push(pageShell(closing,pageNo++,doc.label));
  return pages.join('');
}


// ===== v1.3 TEMPLATE GOVERNANCE AND EDITABLE NUMBERING =====
const TEMPLATE_LIBRARY_STORAGE_KEY_V13 = 'this-instructions-template-library-v13';
const TEMPLATE_EDITOR_SESSION_KEY_V13 = 'this-instructions-template-editor-unlocked';
const TEMPLATE_EDITOR_PASSWORD_V13 = 'THiS2026';
let templateLibraryV13 = null;
let templateEditorStateV13 = { packId: 'smc', docId: 'roadmap', blockId: null };

function cloneV13(value) { return structuredClone(value); }
function slugV13(value) { return String(value || '').toLowerCase().replace(/<[^>]+>/g, ' ').replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, '') || 'section'; }
function packMetaV13(packId) { return packId === 'smc' ? SMC_PACK_META : PACK_DEFINITIONS[packId]; }

function ensureDocNumberingV13(doc) {
  doc.numbering = doc.numbering || {};
  doc.numbering.intro = { mode: 'auto', label: '', ...(doc.numbering.intro || {}) };
  doc.numbering.closing = { mode: 'auto', label: '', ...(doc.numbering.closing || {}) };
  doc.numbering.blocks = doc.numbering.blocks || {};
  doc.timelineSettings = doc.timelineSettings || {};
  (doc.blocks || []).forEach(block => {
    const defaultMode = block.heading === 'arrow' ? 'arrow' : 'auto';
    doc.numbering.blocks[block.id] = { mode: defaultMode, label: '', ...(doc.numbering.blocks[block.id] || {}) };
    doc.timelineSettings[block.id] = doc.timelineSettings[block.id] || {};
  });
  return doc;
}

function numberingConsumesSequenceV13(setting, defaultMode) {
  const mode = setting?.mode || defaultMode || 'auto';
  return mode === 'auto' || mode === 'manual';
}

function headingMarkupV13(setting, autoNumber, title, defaultMode = 'auto') {
  const mode = setting?.mode || defaultMode;
  if (mode === 'arrow') return arrowHeading(title);
  if (mode === 'hidden') return `<div class="number-heading number-heading-plain"><h2>${escapeHtml(title)}</h2></div>`;
  const label = mode === 'manual' && String(setting?.label || '').trim() ? String(setting.label).trim() : autoNumber;
  return numberedHeading(label, title);
}

function rawBlockHtmlV13(block) {
  if (block.templateHtml !== undefined && block.templateHtml !== null) return fillTemplate(block.templateHtml);
  if (activePackId === 'smc') return smcBlockContent(state.selectedDoc, block.id);
  if (block.id === 'checklist') return genericChecklist(state.docs[state.selectedDoc]);
  return fillTemplate(block.html || '');
}

function timelineDescriptorsV13(html) {
  const template = document.createElement('template');
  template.innerHTML = html || '';
  const seen = {};
  return [...template.content.querySelectorAll('.timeline-item')].map((item, index) => {
    const title = item.querySelector('h3')?.textContent?.trim() || `Step ${index + 1}`;
    const base = slugV13(title);
    seen[base] = (seen[base] || 0) + 1;
    return { key: `${base}-${seen[base]}`, title, index };
  });
}

function transformTimelineHtmlV13(html, doc, block) {
  const template = document.createElement('template');
  template.innerHTML = html || '';
  const settings = ensureDocNumberingV13(doc).timelineSettings[block.id] || {};
  const seen = {};
  let visibleNumber = 0;
  [...template.content.querySelectorAll('.timeline-item')].forEach((item, index) => {
    const title = item.querySelector('h3')?.textContent?.trim() || `Step ${index + 1}`;
    const base = slugV13(title);
    seen[base] = (seen[base] || 0) + 1;
    const key = `${base}-${seen[base]}`;
    const setting = { enabled: true, mode: 'auto', label: '', ...(settings[key] || {}) };
    if (setting.enabled === false) { item.remove(); return; }
    visibleNumber += 1;
    const badge = item.querySelector('.timeline-step');
    if (!badge) return;
    if (setting.mode === 'hidden') {
      badge.remove();
      item.classList.add('timeline-item-no-number');
    } else {
      badge.textContent = setting.mode === 'manual' && String(setting.label || '').trim() ? String(setting.label).trim() : `Step ${visibleNumber}`;
    }
  });
  return template.innerHTML;
}

function sectionPlanV13(doc) {
  ensureDocNumberingV13(doc);
  let next = 1;
  const introSetting = doc.numbering.intro;
  const plan = { intro: { setting: introSetting, number: next } };
  if (numberingConsumesSequenceV13(introSetting, 'auto')) next += 1;
  plan.blocks = {};
  doc.blocks.filter(block => block.enabled).forEach(block => {
    const defaultMode = block.heading === 'arrow' ? 'arrow' : 'auto';
    const setting = doc.numbering.blocks[block.id] || { mode: defaultMode, label: '' };
    plan.blocks[block.id] = { setting, number: next, defaultMode };
    if (numberingConsumesSequenceV13(setting, defaultMode)) next += 1;
  });
  plan.closing = { setting: doc.numbering.closing, number: next };
  return plan;
}

function genericBlockHtmlV13(block, planEntry, doc) {
  let body = rawBlockHtmlV13(block);
  body = transformTimelineHtmlV13(body, doc, block);
  const heading = headingMarkupV13(planEntry.setting, planEntry.number, block.title, planEntry.defaultMode);
  const enhanced = v12SafeClientHtml(body) + v12RequirementEnhancement(block, doc);
  return flowSection(`${heading}${enhanced}`);
}

genericBlockHtml = function(block, index) {
  const doc = ensureDocNumberingV13(state.docs[state.selectedDoc]);
  const plan = sectionPlanV13(doc);
  return genericBlockHtmlV13(block, plan.blocks[block.id], doc);
};

v12NextThreeSection = function(doc, planEntry) {
  const priorities = v12PriorityItems(doc);
  const rows = priorities.map((item,index)=>`<div class="next-three-row"><span class="next-three-number">${index+1}</span><div><h3>${['Start with the first priority','Prepare and name the evidence','Tell us about any issue'][index]}</h3><p>${escapeHtml(item)}</p></div></div>`).join('');
  return flowSection(`${headingMarkupV13(planEntry.setting, planEntry.number, 'Your next three steps', 'auto')}<div class="next-three"><div class="next-three-list">${rows}</div></div>`, true);
};

renderStructuredDoc = function(doc) {
  ensureDocNumberingV13(doc);
  const enabled = doc.blocks.filter(block => block.enabled);
  const plan = sectionPlanV13(doc);
  const pages = [coverPage(doc)];
  let pageNo = 1;
  pages.push(v12AtAGlancePage(doc,pageNo++));
  const introText = v12SafeClientHtml(fillTemplate(doc.intro || ''));
  const introParagraphs = introText.split(/\n\s*\n/).filter(Boolean).map(item => `<p>${item}</p>`).join('');
  const noteText = v12SafeClientHtml(fillTemplate(doc.caseNote || ''));
  const intro = flowSection(`${headingMarkupV13(plan.intro.setting, plan.intro.number, 'Introduction', 'auto')}<p>Dear ${escapeHtml(state.client.firstName || 'Client')}</p>${introParagraphs}${noteText?`<div class="callout"><span class="callout-icon">i</span><p>${noteText}</p></div>`:''}`);
  let groups=[]; let current=[intro]; let units=textUnits(intro); const capacity=4300;
  enabled.forEach(block => {
    const rendered = genericBlockHtmlV13(block, plan.blocks[block.id], doc);
    const nextUnits = textUnits(rendered);
    if ((block.forcePage || units + nextUnits > capacity) && current.length) { groups.push(current); current=[]; units=0; }
    current.push(rendered); units += nextUnits;
  });
  if (current.length) groups.push(current);
  groups.forEach(group => pages.push(pageShell(group.join(''),pageNo++,doc.label)));
  const closing = `${v12NextThreeSection(doc, plan.closing)}${flowSection(signoff(),true)}`;
  pages.push(pageShell(closing,pageNo++,doc.label));
  return pages.join('');
};

function numberingRowV13(label, setting, key, options = {}) {
  const modes = [
    ['auto','Automatic'],['manual','Custom label'],['hidden','No number'],['arrow','Arrow heading']
  ];
  return `<div class="numbering-row" data-numbering-key="${escapeHtml(key)}">
    <div class="numbering-row-copy"><strong>${escapeHtml(label)}</strong>${options.note ? `<small>${escapeHtml(options.note)}</small>` : ''}</div>
    <select class="mini-input numbering-mode" data-numbering-mode="${escapeHtml(key)}">${modes.map(([value,text])=>`<option value="${value}" ${(setting.mode||options.defaultMode||'auto')===value?'selected':''}>${text}</option>`).join('')}</select>
    <input class="mini-input numbering-label" data-numbering-label="${escapeHtml(key)}" value="${escapeHtml(setting.label || '')}" placeholder="e.g. 2A" ${(setting.mode||'auto')==='manual'?'':'hidden'}>
  </div>`;
}

function renderNumberingEditorV13() {
  let host = $('#numbering-editor-v13');
  if (!host) {
    const section = document.createElement('div');
    section.className = 'form-section numbering-editor-section';
    section.innerHTML = `<div class="field-heading-row"><label class="field-label">Heading numbers and steps</label><button class="text-button" id="reset-numbering-v13" type="button">Reset</button></div><div class="field-help">Automatic numbers update when sections or steps are removed. Choose a custom label or hide the number without removing the heading.</div><div id="numbering-editor-v13" class="numbering-editor"></div>`;
    const blockSection = $('#block-editor')?.closest('.form-section');
    blockSection?.insertAdjacentElement('afterend', section);
    host = $('#numbering-editor-v13');
  }
  const doc = ensureDocNumberingV13(state.docs[state.selectedDoc]);
  let html = numberingRowV13('Introduction', doc.numbering.intro, 'intro', { note: 'Opening section' });
  doc.blocks.forEach(block => {
    const setting = doc.numbering.blocks[block.id];
    html += numberingRowV13(block.title, setting, `block:${block.id}`, { note: block.enabled ? 'Included section' : 'Section currently excluded', defaultMode: block.heading === 'arrow' ? 'arrow' : 'auto' });
    const source = rawBlockHtmlV13(block);
    const steps = timelineDescriptorsV13(source);
    if (steps.length) {
      const stepSettings = doc.timelineSettings[block.id] || {};
      html += `<div class="timeline-step-editor"><span class="timeline-step-editor-title">Steps within ${escapeHtml(block.title)}</span>${steps.map(step => {
        const current = { enabled: true, mode: 'auto', label: '', ...(stepSettings[step.key] || {}) };
        return `<div class="timeline-edit-row" data-timeline-block="${escapeHtml(block.id)}" data-timeline-key="${escapeHtml(step.key)}">
          <label class="timeline-include"><input type="checkbox" data-timeline-enabled="1" ${current.enabled!==false?'checked':''}><span>${escapeHtml(step.title)}</span></label>
          <select class="mini-input" data-timeline-mode="1"><option value="auto" ${current.mode==='auto'?'selected':''}>Automatic</option><option value="manual" ${current.mode==='manual'?'selected':''}>Custom label</option><option value="hidden" ${current.mode==='hidden'?'selected':''}>No number</option></select>
          <input class="mini-input" data-timeline-label="1" value="${escapeHtml(current.label||'')}" placeholder="e.g. Stage A" ${current.mode==='manual'?'':'hidden'}>
        </div>`;
      }).join('')}</div>`;
    }
  });
  html += numberingRowV13('Your next three steps', doc.numbering.closing, 'closing', { note: 'Final action section' });
  host.innerHTML = html;

  host.querySelectorAll('[data-numbering-mode]').forEach(control => control.addEventListener('change', event => {
    const key = event.target.dataset.numberingMode;
    const target = key === 'intro' || key === 'closing' ? doc.numbering[key] : doc.numbering.blocks[key.replace('block:','')];
    target.mode = event.target.value;
    const row = event.target.closest('.numbering-row');
    row.querySelector('.numbering-label').hidden = target.mode !== 'manual';
    $('#save-status').textContent = 'Draft not saved';
    renderPreview();
  }));
  host.querySelectorAll('[data-numbering-label]').forEach(control => control.addEventListener('input', event => {
    const key = event.target.dataset.numberingLabel;
    const target = key === 'intro' || key === 'closing' ? doc.numbering[key] : doc.numbering.blocks[key.replace('block:','')];
    target.label = event.target.value;
    $('#save-status').textContent = 'Draft not saved';
    renderPreview();
  }));
  host.querySelectorAll('.timeline-edit-row').forEach(row => {
    const blockId = row.dataset.timelineBlock;
    const key = row.dataset.timelineKey;
    const target = doc.timelineSettings[blockId][key] = { enabled:true, mode:'auto', label:'', ...(doc.timelineSettings[blockId][key] || {}) };
    row.querySelector('[data-timeline-enabled]').addEventListener('change', event => { target.enabled = event.target.checked; $('#save-status').textContent='Draft not saved'; renderPreview(); });
    row.querySelector('[data-timeline-mode]').addEventListener('change', event => { target.mode = event.target.value; row.querySelector('[data-timeline-label]').hidden = target.mode !== 'manual'; $('#save-status').textContent='Draft not saved'; renderPreview(); });
    row.querySelector('[data-timeline-label]').addEventListener('input', event => { target.label = event.target.value; $('#save-status').textContent='Draft not saved'; renderPreview(); });
  });
  if ($('#reset-numbering-v13')) $('#reset-numbering-v13').onclick = () => {
    if (!confirm('Reset heading and step numbering for this guide?')) return;
    delete doc.numbering;
    delete doc.timelineSettings;
    ensureDocNumberingV13(doc);
    renderEditor();
    renderPreview();
  };
}

const renderEditorV121 = renderEditor;
renderEditor = function() {
  renderEditorV121();
  renderNumberingEditorV13();
};

function compactBlockV13(block) {
  const copy = {};
  ['id','title','note','enabled','shared','forcePage','heading','html','templateHtml'].forEach(key => { if (block[key] !== undefined) copy[key] = cloneV13(block[key]); });
  return copy;
}
function compactDocV13(doc) {
  ensureDocNumberingV13(doc);
  const copy = {};
  ['label','shortLabel','icon','enabled','stage','description','coverTitle','coverSubtitle','intro','caseNote','renderType'].forEach(key => { if (doc[key] !== undefined) copy[key] = cloneV13(doc[key]); });
  copy.numbering = cloneV13(doc.numbering);
  copy.timelineSettings = cloneV13(doc.timelineSettings);
  copy.blocks = (doc.blocks || []).map(compactBlockV13);
  return copy;
}
function compactTemplateFromStateV13(packId, packState) {
  const meta = packMetaV13(packId);
  return {
    packId,
    title: meta.title,
    version: meta.version || 'May 2026',
    sourcePack: meta.sourcePack || '',
    issueName: meta.issueName || packState.issueName || '',
    initialLabel: meta.initialLabel || 'Initial issue',
    milestoneLabel: meta.milestoneLabel || 'Later-stage guides',
    docs: Object.fromEntries(Object.entries(packState.docs).map(([id,doc]) => [id, compactDocV13(doc)]))
  };
}
function mergeCompactDocV13(baseDoc, templateDoc) {
  const merged = { ...baseDoc, ...cloneV13(templateDoc), hero: baseDoc.hero };
  merged.blocks = cloneV13(templateDoc.blocks || baseDoc.blocks || []);
  ensureDocNumberingV13(merged);
  return merged;
}
function applyCompactTemplateToStateV13(packState, template) {
  const next = cloneV13(packState);
  next.issueName = template.issueName || next.issueName;
  Object.entries(template.docs || {}).forEach(([id,doc]) => {
    if (next.docs[id]) next.docs[id] = mergeCompactDocV13(next.docs[id], doc);
  });
  return next;
}
function applyTemplateToMasterV13(packId, template) {
  if (packId === 'smc') {
    SMC_PACK_META.title = template.title;
    SMC_PACK_META.version = template.version;
    SMC_PACK_META.sourcePack = template.sourcePack;
    SMC_PACK_META.issueName = template.issueName;
    SMC_PACK_META.initialLabel = template.initialLabel;
    SMC_PACK_META.milestoneLabel = template.milestoneLabel;
    const fresh = cloneV13(SMC_DEFAULT_STATE);
    Object.entries(template.docs || {}).forEach(([id,doc]) => { if (fresh.docs[id]) fresh.docs[id] = mergeCompactDocV13(fresh.docs[id], doc); });
    SMC_DEFAULT_STATE.docs = fresh.docs;
  } else {
    const pack = PACK_DEFINITIONS[packId];
    pack.title = template.title;
    pack.version = template.version;
    pack.sourcePack = template.sourcePack;
    pack.issueName = template.issueName;
    pack.initialLabel = template.initialLabel;
    pack.milestoneLabel = template.milestoneLabel;
    Object.entries(template.docs || {}).forEach(([id,doc]) => { if (pack.docs[id]) pack.docs[id] = mergeCompactDocV13(pack.docs[id], doc); });
  }
  PACK_LABELS[packId] = template.title;
}
function initialTemplateEntryV13(packId) {
  const snapshot = compactTemplateFromStateV13(packId, createPackState(packId));
  return { draft: cloneV13(snapshot), published: cloneV13(snapshot), versions: [{ id:'v1.0', createdAt:new Date().toISOString(), note:'Source prototype baseline', snapshot:cloneV13(snapshot) }] };
}
function loadTemplateLibraryV13() {
  let loaded = null;
  try { loaded = JSON.parse(THIS_LOCAL_STORAGE.getItem(TEMPLATE_LIBRARY_STORAGE_KEY_V13) || 'null'); } catch (error) { console.warn('Unable to load template library', error); }
  const library = loaded || { packs:{} };
  library.packs = library.packs || {};
  PACK_ORDER.forEach(packId => { if (!library.packs[packId]) library.packs[packId] = initialTemplateEntryV13(packId); });
  PACK_ORDER.forEach(packId => { if (library.packs[packId].published) applyTemplateToMasterV13(packId, library.packs[packId].published); });
  return library;
}
function saveTemplateLibraryV13() { THIS_LOCAL_STORAGE.setItem(TEMPLATE_LIBRARY_STORAGE_KEY_V13, JSON.stringify(templateLibraryV13)); }
function templateEntryV13(packId = templateEditorStateV13.packId) { return templateLibraryV13.packs[packId]; }
function templateDraftV13() { return templateEntryV13().draft; }
function selectedTemplateDocV13() { return templateDraftV13().docs[templateEditorStateV13.docId]; }
function selectedTemplateBlockV13() { return selectedTemplateDocV13()?.blocks?.find(block => block.id === templateEditorStateV13.blockId) || null; }

