(function () {
  const V152_VERSION = 'v1.5.2';
  document.title = 'THiS Instructions Studio - Template Governance v1.5.2';
  const productSubtitleV152 = document.querySelector('.product-subtitle');
  if (productSubtitleV152) productSubtitleV152.textContent = 'Client-specific guide prototype v1.5.2';

  function glanceDocumentIdV152(packId, docs) {
    const allEntries = Object.entries(docs || {}).filter(([, doc]) => Boolean(doc));
    if (!allEntries.length) return null;
    const explicit = allEntries.find(([id, doc]) => {
      const text = `${id} ${doc.label || ''} ${doc.shortLabel || ''} ${doc.coverTitle || ''}`.toLowerCase();
      return id === 'roadmap' || /introduction\s*(?:&|and)?\s*road\s*-?\s*map/.test(text) || /introduction.*roadmap/.test(text);
    });
    if (explicit) return explicit[0];
    const firstEnabled = allEntries.find(([, doc]) => doc.enabled !== false);
    return (firstEnabled || allEntries[0])[0];
  }

  function shouldShowGlanceV152(packId, docId, docs) {
    return Boolean(docId && docId === glanceDocumentIdV152(packId, docs));
  }

  let renderingDocIdV152 = null;
  const renderDocHtmlBeforeV152 = renderDocHtml;
  renderDocHtml = function (id) {
    const previous = renderingDocIdV152;
    renderingDocIdV152 = id;
    try {
      return renderDocHtmlBeforeV152(id);
    } finally {
      renderingDocIdV152 = previous;
    }
  };

  // The at-a-glance page belongs to the pack, not every guide. It is rendered
  // only in the pack's introduction/road-map guide, or in the first guide where
  // the pack is a single-document pack.
  renderStructuredDoc = function (doc) {
    ensureDocNumberingV13(doc);
    const enabled = doc.blocks.filter(block => block.enabled);
    const plan = sectionPlanV13(doc);
    const pages = [coverPage(doc)];
    let pageNo = 1;
    const docId = renderingDocIdV152 || state.selectedDoc;
    if (shouldShowGlanceV152(activePackId, docId, state.docs)) {
      pages.push(v12AtAGlancePage(doc, pageNo++));
    }
    const introParagraphs = editedIntroParagraphsV14(doc);
    const noteText = editedCaseNoteV14(doc);
    const intro = flowSection(`${headingMarkupV13(plan.intro.setting, plan.intro.number, 'Introduction', 'auto')}<p>Dear ${escapeHtml(state.client.firstName || 'Client')}</p>${introParagraphs}${noteText ? `<div class="callout"><span class="callout-icon">i</span><p>${noteText}</p></div>` : ''}`);
    let groups = [];
    let current = [intro];
    let units = textUnits(intro);
    const capacity = 4300;
    enabled.forEach(block => {
      const rendered = genericBlockHtmlV13(block, plan.blocks[block.id], doc);
      const nextUnits = textUnits(rendered);
      if ((block.forcePage || units + nextUnits > capacity) && current.length) {
        groups.push(current);
        current = [];
        units = 0;
      }
      current.push(rendered);
      units += nextUnits;
    });
    if (current.length) groups.push(current);
    groups.forEach(group => pages.push(pageShell(group.join(''), pageNo++, doc.label)));
    const closing = `${v12NextThreeSection(doc, plan.closing)}${flowSection(signoff(), true)}`;
    pages.push(pageShell(closing, pageNo++, doc.label));
    return pages.join('');
  };

  // Only show the permanent at-a-glance template controls on the guide that
  // actually contains that page.
  const renderTemplateFormBeforeV152 = renderTemplateFormV13;
  renderTemplateFormV13 = function () {
    renderTemplateFormBeforeV152();
    const form = document.querySelector('#template-form-v13');
    if (!form) return;
    const packId = templateEditorStateV13.packId;
    const draft = templateDraftV13();
    const docId = templateEditorStateV13.docId;
    if (!shouldShowGlanceV152(packId, docId, draft.docs)) {
      form.querySelector('.template-glance-editor-v15')?.remove();
    }
  };

  function ensureCoverSubtitleControlV152() {
    let section = document.querySelector('#cover-subtitle-section-v152');
    if (!section) {
      const titleInput = document.querySelector('#document-title');
      const titleSection = titleInput?.closest('.form-section');
      if (!titleSection) return null;
      section = document.createElement('div');
      section.className = 'form-section';
      section.id = 'cover-subtitle-section-v152';
      section.innerHTML = `<label class="field-label" for="document-subtitle-v152">Cover subtitle</label><input class="text-input" id="document-subtitle-v152" type="text"><div class="field-help">Both title-page headings can also be edited directly in the preview while Edit text is active.</div>`;
      titleSection.insertAdjacentElement('afterend', section);
      const input = section.querySelector('#document-subtitle-v152');
      input.addEventListener('input', event => {
        const doc = state.docs[state.selectedDoc];
        if (!doc) return;
        doc.coverSubtitle = event.target.value;
        document.querySelector('#save-status').textContent = 'Draft not saved';
        renderPreview();
      });
    }
    return section.querySelector('#document-subtitle-v152');
  }

  const renderEditorBeforeV152 = renderEditor;
  renderEditor = function () {
    renderEditorBeforeV152();
    const input = ensureCoverSubtitleControlV152();
    if (input) input.value = state.docs[state.selectedDoc]?.coverSubtitle || '';
  };

  // Make the two title-page headings editable in the ordinary client preview as
  // well as in the master Template Editor. These edits update the draft fields,
  // rather than creating a fixed text override.
  function bindClientCoverHeadingV152(node, docId, field, singleLine = true) {
    if (!node) return;
    node.classList.add('inline-editable');
    node.contentEditable = inlineEditMode ? 'true' : 'false';
    node.spellcheck = inlineEditMode;
    if (!inlineEditMode) return;
    const doc = state.docs[docId];
    const original = String(doc?.[field] || '').trim();
    node.addEventListener('keydown', event => {
      if (event.key === 'Escape') {
        node.textContent = original;
        node.blur();
      }
      if (singleLine && event.key === 'Enter') {
        event.preventDefault();
        node.blur();
      }
    });
    node.addEventListener('input', () => {
      document.querySelector('#save-status').textContent = 'Unsaved text edits';
    });
    node.addEventListener('blur', () => {
      const value = (node.innerText || node.textContent || '').replace(/\s+/g, ' ').trim();
      if (!value) {
        renderPreview();
        return;
      }
      doc[field] = value;
      document.querySelector('#save-status').textContent = 'Draft not saved';
      renderEditor();
      renderDocumentLists();
      renderPreview();
    });
  }

  const applyInlineEditsBeforeV152 = applyInlineEdits;
  applyInlineEdits = function (root, docId, makeEditable = false) {
    applyInlineEditsBeforeV152(root, docId, makeEditable);
    const priorMode = inlineEditMode;
    inlineEditMode = makeEditable;
    bindClientCoverHeadingV152(root.querySelector('.pdf-cover .cover-title'), docId, 'coverTitle');
    bindClientCoverHeadingV152(root.querySelector('.pdf-cover .cover-subtitle'), docId, 'coverSubtitle');
    inlineEditMode = priorMode;
  };

  // Refresh the already-rendered interface so the conditional page and the new
  // cover-subtitle control are immediately visible.
  renderAll();
})();



(function(){
  const CRM_ORIGIN = window.location.origin;
  let crmContext = { instructionSetId:'', canManageTemplates:false };
  let crmInitialised = false;
  let readyHandshakeTimer = 0;
  let lastPublishedVersions = {};

  function clone(value){ return JSON.parse(JSON.stringify(value == null ? {} : value)); }
  function post(type, payload={}){
    if (window.parent === window) return;
    window.parent.postMessage({ source:'this-instructions-studio', type, ...payload }, CRM_ORIGIN);
  }
  function packFromCaseType(caseType=''){
    const value=String(caseType||'').toLowerCase();
    if(value.includes('smc')||value.includes('skilled migrant')) return 'smc';
    if(value.includes('active investor')||value.includes('investor')) return 'investor';
    if(value.includes('parent')) return 'parent';
    if(value.includes('partner residence')||value.includes('partnership residence')) return 'family';
    if(value.includes('partner wv')||value.includes('partnership work')) return 'pwv';
    if(value.includes('aewv')) return 'aewv';
    if(value.includes('citizenship')) return 'citizenship';
    if(value.includes('permanent residence')) return 'permanent';
    if(value.includes('student')) return 'student';
    if(value.includes('visitor')) return 'visitor';
    return 'smc';
  }
  function mapCrmClient(client={}, advisers=[]){
    const family=Array.isArray(client.familyMembers)?client.familyMembers:[];
    const partner=family.find(member=>/partner|spouse|husband|wife/i.test(member.relationship||member.type||member.role||''));
    const children=family.filter(member=>/child|son|daughter|depend/i.test(member.relationship||member.type||member.role||''));
    const primary=advisers.find(item=>item.id===client.primaryAdviserId) || {};
    const principal=[client.firstName,client.lastName].filter(Boolean).join(' ').trim();
    const partnerName=partner?.name || [partner?.firstName,partner?.lastName].filter(Boolean).join(' ').trim();
    const childNames=children.map(member=>member.name || [member.firstName,member.lastName].filter(Boolean).join(' ').trim()).filter(Boolean);
    const allNames=[principal,partnerName,...childNames].filter(Boolean);
    return {
      firstName:client.firstName||'', lastName:client.lastName||'', preparedFor:allNames.length>1?allNames.join(', ').replace(/, ([^,]*)$/, ' and $1'):principal,
      partnerName, children:childNames.join(', '), adviser:primary.name||'', adviserLicence:primary.licence||'',
      applicationType:client.caseType||'', pathway:client.caseStrategy||client.caseType||'', requiredFor:allNames.join(', '),
      nationality:client.nationality||'', dateOfBirth:client.dateOfBirth||'', location:client.location||'', email:client.email||'', phone:client.phone||'',
      matterName:client.matterName||'', oneLawClientNumber:client.oneLawClientNumber||''
    };
  }
  function createBlankPack(packId, clientData, advisers, standaloneLabel){
    const next=createPackState(packId);
    const mapped=clientData?mapCrmClient(clientData,advisers):{};
    Object.keys(next.client||{}).forEach(key=>{ next.client[key]=''; });
    Object.assign(next.client,mapped);
    if(!clientData && standaloneLabel){
      next.client.preparedFor=standaloneLabel;
      next.client.firstName=standaloneLabel;
      next.client.requiredFor=standaloneLabel;
    }
    next.policeClearances=[];
    next.preparedDate=new Date().toISOString().slice(0,10);
    next.contentStatus='Draft - adviser review required';
    return next;
  }
  function applyTemplateLibrary(library){
    if(!library || typeof library!=='object' || !library.packs) return;
    templateLibraryV13=clone(library);
    PACK_ORDER.forEach(packId=>{
      if(!templateLibraryV13.packs[packId]) templateLibraryV13.packs[packId]=initialTemplateEntryV13(packId);
      const published=templateLibraryV13.packs[packId]?.published;
      if(published) applyTemplateToMasterV13(packId,published);
      const versions=templateLibraryV13.packs[packId]?.versions||[];
      lastPublishedVersions[packId]=versions[versions.length-1]?.id||'';
    });
  }
  function serialiseActivePack(packState){
    const copy=clone(packState||{});
    Object.values(copy.docs||{}).forEach(doc=>{ if(doc && typeof doc==='object') delete doc.hero; });
    return copy;
  }
  function currentSnapshot(){
    workspaceDrafts[activePackId]=state;
    return {
      activePackId,
      packState:serialiseActivePack(state),
      selectedDoc:state?.selectedDoc||'',
      preparedDate:state?.preparedDate||'',
      title:state?.issueName||currentPack()?.title||'Instruction set',
      templateVersion:Object.fromEntries(PACK_ORDER.map(id=>{
        const versions=templateLibraryV13?.packs?.[id]?.versions||[];
        return [id,versions[versions.length-1]?.id||''];
      }))
    };
  }
  function emitSnapshot(reason='save'){
    post('THIS_STUDIO_SNAPSHOT',{reason,instructionSetId:crmContext.instructionSetId,snapshot:currentSnapshot()});
  }
  function emitTemplateLibrary(reason='save'){
    let versionEvent=null;
    if(reason==='publish'){
      const packId=templateEditorStateV13?.packId||activePackId;
      const versions=templateLibraryV13?.packs?.[packId]?.versions||[];
      const latest=versions[versions.length-1];
      if(latest && latest.id!==lastPublishedVersions[packId]){
        versionEvent={packId,versionLabel:latest.id,changeNote:latest.note||'',snapshot:clone(latest.snapshot||{})};
        lastPublishedVersions[packId]=latest.id;
      }
    }
    post('THIS_STUDIO_TEMPLATE_LIBRARY',{reason,library:clone(templateLibraryV13||{}),versionEvent});
  }
  function setCrmPresentation(){
    document.body.classList.add('crm-embedded-studio');
    const subtitle=document.querySelector('.product-subtitle'); if(subtitle) subtitle.textContent='CRM instruction authoring';
    const banner=document.querySelector('#prototype-banner'); if(banner){ banner.textContent='Review client facts and current policy before issue'; }
    const reset=document.querySelector('#reset-draft'); if(reset) reset.textContent='Reset draft';
    const save=document.querySelector('#save-draft'); if(save) save.textContent='Save to CRM';
    const publish=document.querySelector('#publish-pack'); if(publish) publish.textContent='Mark ready';
    const confirmPublish=document.querySelector('#confirm-publish'); if(confirmPublish) confirmPublish.textContent='Mark ready';
    const publishTitle=document.querySelector('#publish-title'); if(publishTitle) publishTitle.textContent='Ready for issue';
    document.querySelectorAll('.field-help').forEach(node=>{ node.innerHTML=node.innerHTML.replace(/prototype/gi,'draft').replace(/CRM data remains separate and is inserted automatically\.?/gi,'Client data is inserted from the linked CRM record and remains editable in this draft.'); });
  }
  function initFromCrm(payload){
    crmContext={instructionSetId:payload.instructionSet?.id||'',canManageTemplates:Boolean(payload.canManageTemplates)};
    if(payload.templateLibrary?.packs) applyTemplateLibrary(payload.templateLibrary);
    if(crmContext.canManageTemplates){ try{ THIS_SESSION_STORAGE.setItem(TEMPLATE_EDITOR_SESSION_KEY_V13,'1'); }catch{} }
    else { document.querySelector('#open-template-library-v13')?.remove(); }
    const saved=payload.instructionSet?.studioState||{};
    if(saved.packState && typeof saved.packState==='object'){
      activePackId=PACK_ORDER.includes(saved.activePackId)?saved.activePackId:(payload.instructionSet?.packId||'smc');
      workspaceDrafts={};
      PACK_ORDER.forEach(id=>{ workspaceDrafts[id]=createPackState(id); });
      workspaceDrafts[activePackId]=normalisePackState(activePackId,saved.packState);
    }else if(saved.workspaceDrafts && typeof saved.workspaceDrafts==='object'){
      workspaceDrafts=clone(saved.workspaceDrafts);
      PACK_ORDER.forEach(id=>{ workspaceDrafts[id]=normalisePackState(id,workspaceDrafts[id]); });
      activePackId=PACK_ORDER.includes(saved.activePackId)?saved.activePackId:(payload.instructionSet?.packId||'smc');
    }else{
      activePackId=payload.instructionSet?.packId||packFromCaseType(payload.client?.caseType||'');
      workspaceDrafts={};
      PACK_ORDER.forEach(id=>{ workspaceDrafts[id]=createPackState(id); });
      workspaceDrafts[activePackId]=createBlankPack(activePackId,payload.client||null,payload.advisers||[],payload.instructionSet?.standaloneLabel||'');
    }
    state=workspaceDrafts[activePackId];
    if(payload.client){
      const mappedClient=mapCrmClient(payload.client,payload.advisers||[]);
      state.client={...(state.client||{})};
      Object.entries(mappedClient).forEach(([key,value])=>{
        if(value!=='' && value!=null) state.client[key]=value;
      });
    }
    if(payload.instructionSet?.title) state.issueName=payload.instructionSet.title;
    crmInitialised=true;
    if(readyHandshakeTimer) window.clearInterval(readyHandshakeTimer);
    renderAll();
    setCrmPresentation();
    post('THIS_STUDIO_INITIALISED',{instructionSetId:crmContext.instructionSetId,activePackId});
  }
  window.__THIS_STUDIO_INIT__=initFromCrm;
  window.addEventListener('message',event=>{
    if(event.origin!==CRM_ORIGIN || event.source!==window.parent) return;
    const message=event.data||{};
    if(message.type==='THIS_STUDIO_INIT') initFromCrm(message.payload||{});
    if(message.type==='THIS_STUDIO_REQUEST_SNAPSHOT') emitSnapshot(message.reason||'request');
    if(message.type==='THIS_STUDIO_SET_STATUS' && state){ state.contentStatus=message.status||state.contentStatus; renderPackSettings(); }
  });
  window.addEventListener('load',()=>{
    setCrmPresentation();
    document.querySelector('#save-draft')?.addEventListener('click',()=>setTimeout(()=>emitSnapshot('save'),30));
    document.querySelector('#confirm-publish')?.addEventListener('click',()=>setTimeout(()=>emitSnapshot('ready'),40));
    document.body.addEventListener('click',event=>{
      if(event.target.closest('#template-save-draft-v13')) setTimeout(()=>emitTemplateLibrary('save'),60);
      if(event.target.closest('#template-publish-version-v13')) setTimeout(()=>emitTemplateLibrary('publish'),120);
      if(event.target.closest('#template-reset-draft-v13')||event.target.closest('[data-restore-version-v13]')) setTimeout(()=>emitTemplateLibrary('save'),80);
    });
    const announceReady=()=>{ if(!crmInitialised) post('THIS_STUDIO_READY'); };
    announceReady();
    readyHandshakeTimer=window.setInterval(announceReady,750);
    window.setTimeout(()=>{ if(readyHandshakeTimer) window.clearInterval(readyHandshakeTimer); },15000);
  });
})();
